{
  "name": "OPC-UA 地址空间构建器",
  "name_en": "OPC-UA Address Space Builder",
  "manufacturer": "",
  "description": "这是一个用于 OPC-UA 服务器的数据模型构建软件组件，可根据配置生成变量节点、结构体对象及数组节点，并维护变量索引、节点权限与变量映射。它常用于实验室自动化或仪器集成场景中组织设备数据点与通信地址空间。",
  "description_en": "This is a software component for building an OPC-UA server data model. It creates variable nodes, structured objects, and array nodes from configuration, and maintains variable indices, node permissions, and variable mappings. It is commonly used in laboratory automation or instrument integration workflows to organize device data points and communication address spaces.",
  "actions": [
    {
      "action_name": "auto-build",
      "description": "根据配置构建 OPC-UA 地址空间节点。",
      "description_en": "Build the OPC-UA address space nodes from configuration."
    },
    {
      "action_name": "auto-get_variable_indices",
      "description": "获取变量索引列表。",
      "description_en": "get the list of variable indices"
    }
  ],
  "tag_hints": [
    "OPC UA",
    "address space modeling",
    "server node configuration",
    "industrial communication",
    "variable node mapping"
  ]
}

